import Link from 'next/link'
import { ArrowLeft, ChevronRight } from 'lucide-react'
import { cn } from '@/lib/utils'
import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from '@/components/ui/breadcrumb'

interface BreadcrumbItemDef {
  label: string
  href?: string // absent = current page (not a link)
}

interface PageHeaderProps {
  title: string
  description?: string         // replaces old `subtitle`
  actions?: React.ReactNode    // replaces old `right`
  breadcrumb?: BreadcrumbItemDef[]
  backHref?: string            // renders a back button/link before title
  className?: string
}

export function PageHeader({
  title,
  description,
  actions,
  breadcrumb,
  backHref,
  className,
}: PageHeaderProps) {
  return (
    <div
      className={cn(
        'relative flex flex-col gap-1 sm:flex-row sm:items-start sm:justify-between',
        // Hairline rust divider — brand signature, anchored flush at the bottom
        // of the header's own box (not leaking into sibling space). `pb-3` gives
        // the hairline breathing room under the description; the 24px rhythm to
        // the next zone is owned by PageShell's `space-y-6`.
        'pb-3',
        "after:pointer-events-none after:absolute after:bottom-0 after:left-0 after:h-px after:w-10 after:bg-[linear-gradient(to_right,_oklch(58%_0.16_35/_0.6),_transparent)]",
        className,
      )}
    >
      {/* Left column */}
      <div className="flex flex-col gap-1 min-w-0">
        {/* Back link */}
        {backHref && (
          <Link
            href={backHref}
            className="inline-flex items-center gap-1.5 text-sm text-muted-foreground hover:text-foreground transition-colors mb-1"
          >
            <ArrowLeft className="size-3.5" aria-hidden="true" />
            Back
          </Link>
        )}

        {/* Breadcrumb */}
        {breadcrumb && breadcrumb.length > 0 && (
          <Breadcrumb className="mb-2">
            <BreadcrumbList className="text-[13px]">
              {breadcrumb.map((item, i) => {
                const isLast = i === breadcrumb.length - 1
                return (
                  <BreadcrumbItem key={i}>
                    {isLast ? (
                      <BreadcrumbPage className="text-[13px]">{item.label}</BreadcrumbPage>
                    ) : (
                      <>
                        <BreadcrumbLink
                          render={<Link href={item.href ?? '#'} className="text-[13px]" />}
                        >
                          {item.label}
                        </BreadcrumbLink>
                        <BreadcrumbSeparator>
                          <ChevronRight className="size-3" aria-hidden="true" />
                        </BreadcrumbSeparator>
                      </>
                    )}
                  </BreadcrumbItem>
                )
              })}
            </BreadcrumbList>
          </Breadcrumb>
        )}

        {/* Title — Instrument Serif per brand book */}
        <h1 className="font-display text-[36px] leading-[1.1] text-foreground truncate">
          {title}
        </h1>

        {/* Description */}
        {description && (
          <p className="text-sm text-stone-brand mt-1.5">
            {description}
          </p>
        )}
      </div>

      {/* Actions slot */}
      {actions && (
        <div className="flex shrink-0 items-center gap-2 mt-4 sm:mt-0">
          {actions}
        </div>
      )}
    </div>
  )
}

import type { ReactNode } from 'react'
import { cn } from '@/lib/utils'

interface PageShellProps {
  children: ReactNode
  /**
   * Opt out of default padding for full-height layouts (Calendar, Messages).
   * The page is responsible for its own scroll container + internal padding.
   */
  fullHeight?: boolean
  /** Max content width cap. Default `1440`. Pass `false` to disable the cap. */
  maxWidth?: number | false
  /** Extra classes applied to the outer wrapper. */
  className?: string
  /** Extra classes applied to the inner padded container (ignored when fullHeight). */
  innerClassName?: string
}

/**
 * S18 — Branded page container.
 *
 * Enforces the same gutter + vertical rhythm the TodayClient established as the
 * gold standard: `px-4 sm:px-6 lg:px-8 pt-6 pb-10`, `max-w-[1440px]` cap,
 * background token `--color-page-bg`. Every authenticated page should wrap its
 * content in `<PageShell>`. Full-height layouts (Calendar, Messages) pass
 * `fullHeight` to skip the default padding and handle scroll internally.
 */
export function PageShell({
  children,
  fullHeight = false,
  maxWidth = 1440,
  className,
  innerClassName,
}: PageShellProps) {
  if (fullHeight) {
    return (
      <div className={cn('flex min-h-0 flex-1 flex-col', className)}>
        {children}
      </div>
    )
  }

  return (
    <div
      className={cn(
        // Base page background + dark-aware radial highlight (top-right) + rust
        // whisper (bottom-left). Both tokens flip between light (bone highlight,
        // faint rust) and dark (subtle rust warmth, slightly stronger rust) so
        // the page keeps tonal depth in either theme without blowing out.
        'relative flex min-h-full flex-col bg-[var(--color-page-bg)]',
        'before:pointer-events-none before:absolute before:inset-0',
        'before:bg-[radial-gradient(ellipse_at_top_right,_var(--color-page-highlight)_0%,_transparent_55%)]',
        'after:pointer-events-none after:absolute after:inset-0',
        'after:bg-[radial-gradient(circle_at_bottom_left,_var(--color-page-whisper)_0%,_transparent_45%)]',
        className,
      )}
    >
      <div
        style={
          maxWidth !== false && maxWidth !== 1440
            ? { maxWidth: `${maxWidth}px` }
            : undefined
        }
        className={cn(
          // S24 page-chrome rhythm — every direct child sits on a 24px vertical
          // cadence: PageHeader → PageViews → PageToolbar → content. Sub-24px
          // spacing nests inside a child `flex flex-col gap-*` container.
          // Flex gap (not margin) so children's own mt-* never fights the rhythm.
          'relative z-10 mx-auto w-full flex-1 px-4 pb-10 pt-6 sm:px-6 lg:px-8',
          'flex flex-col gap-6',
          maxWidth === 1440 && 'max-w-[1440px]',
          innerClassName,
        )}
      >
        {children}
      </div>
    </div>
  )
}

import type { ReactNode } from 'react'
import { cn } from '@/lib/utils'

interface PageViewsProps {
  children: ReactNode
  /**
   * Right-aligned slot — record counts, "+ New view", "Manage views",
   * primary CTA for filter-first pages like /clients.
   */
  actions?: ReactNode
  /**
   * Adds a `border-b border-border/60` hairline that spans the full row.
   * Use ONLY when the children element doesn't already render a bottom border
   * (e.g. a `<SavedViewSwitcher>` pill row on /clients). `<PageTabs>` brings
   * its own hairline — leave `bordered` false for tab layouts.
   */
  bordered?: boolean
  className?: string
}

/**
 * S24 — Canonical "view picker" zone directly beneath `<PageHeader>`.
 *
 * Hosts either a `<PageTabs>` row (tabbed index pages) or a
 * `<SavedViewSwitcher>` pill row (filter-first pages) on the left, with an
 * optional actions slot on the right. Adds mobile horizontal scroll + fade
 * masks so overflowing tabs never cause horizontal page shift on narrow
 * viewports.
 *
 * Vertical rhythm is owned by `<PageShell>`'s `space-y-6`. This component
 * never adds its own top/bottom margin.
 */
export function PageViews({
  children,
  actions,
  bordered = false,
  className,
}: PageViewsProps) {
  return (
    <div
      className={cn(
        'flex items-end justify-between gap-3',
        bordered && 'border-b border-border/60',
        className,
      )}
    >
      <div
        className={cn(
          'flex min-w-0 flex-1 items-end',
          'overflow-x-auto scrollbar-none',
          '[mask-image:linear-gradient(to_right,transparent_0px,black_16px,black_calc(100%-16px),transparent_100%)]',
          'md:[mask-image:none]',
        )}
      >
        {children}
      </div>

      {actions && (
        <div className="flex shrink-0 items-center gap-2 pb-2">
          {actions}
        </div>
      )}
    </div>
  )
}

'use client'

import { ChevronDown, Plus, Star } from 'lucide-react'
import { Button } from '@/components/ui/button'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import { cn } from '@/lib/utils'
import type { Database } from '@/lib/supabase/types'

export type ClientView = Database['public']['Tables']['client_views']['Row']

interface SavedViewSwitcherProps {
  views: ClientView[]
  activeViewId: string | null
  onViewChange: (viewId: string | null) => void
  onCreateView: () => void
  onEditView: (view: ClientView) => void
  onDuplicateView: (view: ClientView) => void
  onDeleteView: (viewId: string) => void
  onSetDefault: (view: ClientView) => void
}

export function SavedViewSwitcher({
  views,
  activeViewId,
  onViewChange,
  onCreateView,
  onEditView,
  onDuplicateView,
  onDeleteView,
  onSetDefault,
}: SavedViewSwitcherProps) {
  const activeView = views.find((v) => v.id === activeViewId) ?? null

  function renderDefaultItem(view: ClientView) {
    if (view.is_default) {
      return (
        <DropdownMenuItem disabled className="gap-2 text-xs text-muted-foreground">
          <Star className="h-3.5 w-3.5 fill-rust text-rust" aria-hidden="true" />
          Current default view
        </DropdownMenuItem>
      )
    }
    return (
      <DropdownMenuItem onClick={() => onSetDefault(view)} className="gap-2 text-xs">
        <Star className="h-3.5 w-3.5" aria-hidden="true" />
        Make this my default view
      </DropdownMenuItem>
    )
  }

  return (
    <div
      role="tablist"
      aria-label="Client views"
      className="flex items-center gap-1.5 overflow-x-auto scrollbar-none pb-px"
    >
      {views.map((view) => {
        const isActive = view.id === activeViewId
        const showDropdown = isActive // any active view gets the dropdown (incl. system)

        return (
          <div key={view.id} className="flex shrink-0">
            {showDropdown ? (
              <DropdownMenu>
                <DropdownMenuTrigger
                  render={
                    <Button
                      role="tab"
                      aria-selected={true}
                      aria-current="true"
                      variant="ghost"
                      size="sm"
                      className="h-8 rounded-full px-3 text-xs font-medium bg-primary text-primary-foreground hover:bg-primary/90 gap-1"
                    >
                      {view.is_default && (
                        <Star
                          className="h-3 w-3 shrink-0 fill-rust text-rust"
                          aria-label="Default view"
                        />
                      )}
                      {view.name}
                      <ChevronDown className="h-3.5 w-3.5 shrink-0" aria-hidden="true" />
                    </Button>
                  }
                />
                <DropdownMenuContent align="start">
                  {renderDefaultItem(view)}
                  {!view.is_system && (
                    <>
                      <DropdownMenuSeparator />
                      <DropdownMenuItem onClick={() => onEditView(view)}>
                        Edit view filters
                      </DropdownMenuItem>
                      <DropdownMenuItem onClick={() => onDuplicateView(view)}>
                        Duplicate view
                      </DropdownMenuItem>
                      <DropdownMenuSeparator />
                      <DropdownMenuItem
                        className="text-destructive focus:text-destructive"
                        onClick={() => onDeleteView(view.id)}
                      >
                        Delete view
                      </DropdownMenuItem>
                    </>
                  )}
                </DropdownMenuContent>
              </DropdownMenu>
            ) : (
              <Button
                role="tab"
                aria-selected={isActive}
                {...(view.is_system ? { 'aria-label': `${view.name} (system view, read-only)` } : {})}
                variant="ghost"
                size="sm"
                className={cn(
                  'h-8 rounded-full px-3 text-xs font-medium transition-colors duration-150 ease-out gap-1',
                  isActive
                    ? 'bg-primary text-primary-foreground hover:bg-primary/90'
                    : 'text-muted-foreground hover:text-foreground hover:bg-muted'
                )}
                onClick={() => onViewChange(view.id)}
              >
                {view.is_default && (
                  <Star
                    className="h-3 w-3 shrink-0 fill-rust text-rust"
                    aria-label="Default view"
                  />
                )}
                {view.name}
              </Button>
            )}
          </div>
        )
      })}

      {/* New view button */}
      <Button
        variant="outline"
        size="sm"
        className="h-8 rounded-full px-3 text-xs shrink-0 gap-1"
        onClick={onCreateView}
        aria-label="Create new view"
      >
        <Plus className="h-3.5 w-3.5" aria-hidden="true" />
        New view
      </Button>

      {activeView && !activeView.is_system && (
        <div id="view-unsaved-hint" className="sr-only" aria-live="polite" />
      )}
    </div>
  )
}

'use client'

import { useRef } from 'react'
import { Search, Star, AlertTriangle, X, Tag, UserCircle, Clock, Columns3, Stethoscope, MoreHorizontal, Archive } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Badge } from '@/components/ui/badge'
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '@/components/ui/popover'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from '@/components/ui/command'
import { Checkbox } from '@/components/ui/checkbox'
import { type ClientTag } from './TagChip'
import { cn } from '@/lib/utils'

export interface ClientFilters {
  q: string
  tags: string[]
  vip: boolean
  inactive: boolean
  noShows: boolean
  showArchived: boolean
  hasAlerts: boolean
  spendingTier: '' | '0-500' | '500-2000' | '2000-5000' | '5000+'
  artistIds: string[]
  serviceIds: string[]
  lastVisitRange: '' | '30d' | '90d' | '90d+' | 'never'
}

export interface FilterArtist {
  id: string
  display_name: string
}

export interface FilterService {
  id: string
  name: string
}

interface ClientFilterBarProps {
  filters: ClientFilters
  onChange: (filters: ClientFilters) => void
  tagLibrary: ClientTag[]
  artists?: FilterArtist[]
  services?: FilterService[]
}

const SPENDING_OPTIONS: { value: ClientFilters['spendingTier']; label: string }[] = [
  { value: '', label: 'Any' },
  { value: '0-500', label: '$0 – $500' },
  { value: '500-2000', label: '$500 – $2K' },
  { value: '2000-5000', label: '$2K – $5K' },
  { value: '5000+', label: '$5K+' },
]

const LAST_VISIT_OPTIONS: { value: ClientFilters['lastVisitRange']; label: string }[] = [
  { value: '', label: 'Any time' },
  { value: '30d', label: 'Last 30 days' },
  { value: '90d', label: 'Last 90 days' },
  { value: '90d+', label: '90+ days ago (inactive)' },
  { value: 'never', label: 'Never visited' },
]

export function ClientFilterBar({
  filters,
  onChange,
  tagLibrary,
  artists = [],
  services = [],
}: ClientFilterBarProps) {
  const searchRef = useRef<HTMLInputElement>(null)
  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null)

  function set<K extends keyof ClientFilters>(key: K, value: ClientFilters[K]) {
    onChange({ ...filters, [key]: value })
  }

  function handleSearchChange(e: React.ChangeEvent<HTMLInputElement>) {
    const val = e.target.value
    if (debounceRef.current) clearTimeout(debounceRef.current)
    debounceRef.current = setTimeout(() => {
      set('q', val)
    }, 150)
  }

  function toggleTag(slug: string) {
    const next = filters.tags.includes(slug)
      ? filters.tags.filter((t) => t !== slug)
      : [...filters.tags, slug]
    set('tags', next)
  }

  function toggleArtist(id: string) {
    const next = filters.artistIds.includes(id)
      ? filters.artistIds.filter((a) => a !== id)
      : [...filters.artistIds, id]
    set('artistIds', next)
  }

  function toggleService(id: string) {
    const next = filters.serviceIds.includes(id)
      ? filters.serviceIds.filter((s) => s !== id)
      : [...filters.serviceIds, id]
    set('serviceIds', next)
  }

  function clearAll() {
    onChange({
      q: '',
      tags: [],
      vip: false,
      inactive: false,
      noShows: false,
      showArchived: false,
      hasAlerts: false,
      spendingTier: '',
      artistIds: [],
      serviceIds: [],
      lastVisitRange: '',
    })
    if (searchRef.current) searchRef.current.value = ''
  }

  const hasActiveFilters = Boolean(
    filters.q ||
    filters.tags.length > 0 ||
    filters.vip ||
    filters.noShows ||
    filters.hasAlerts ||
    filters.spendingTier ||
    filters.artistIds.length > 0 ||
    filters.serviceIds.length > 0 ||
    filters.lastVisitRange
  )

  const activeChips: { label: string; onRemove: () => void }[] = []
  if (filters.vip) activeChips.push({ label: 'VIP', onRemove: () => set('vip', false) })
  if (filters.noShows) activeChips.push({ label: 'No-shows', onRemove: () => set('noShows', false) })
  if (filters.hasAlerts) activeChips.push({ label: 'Has alerts', onRemove: () => set('hasAlerts', false) })
  if (filters.spendingTier) {
    const label = SPENDING_OPTIONS.find((o) => o.value === filters.spendingTier)?.label ?? filters.spendingTier
    activeChips.push({ label: `VIP: ${label}`, onRemove: () => set('spendingTier', '') })
  }
  if (filters.lastVisitRange) {
    const label = LAST_VISIT_OPTIONS.find((o) => o.value === filters.lastVisitRange)?.label ?? filters.lastVisitRange
    activeChips.push({ label: `Visit: ${label}`, onRemove: () => set('lastVisitRange', '') })
  }
  for (const slug of filters.tags) {
    const tag = tagLibrary.find((t) => t.name === slug || t.id === slug)
    activeChips.push({ label: tag?.name ?? slug, onRemove: () => toggleTag(slug) })
  }
  for (const id of filters.artistIds) {
    const artist = artists.find((a) => a.id === id)
    activeChips.push({ label: `Artist: ${artist?.display_name ?? id}`, onRemove: () => toggleArtist(id) })
  }
  for (const id of filters.serviceIds) {
    const service = services.find((s) => s.id === id)
    activeChips.push({ label: `Service: ${service?.name ?? id}`, onRemove: () => toggleService(id) })
  }

  return (
    <div className="flex flex-col gap-3">
      {/* Search + filter controls */}
      <div className="flex flex-wrap items-center gap-2">
        {/* Search */}
        <div className="relative max-w-sm w-full sm:w-auto">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-muted-foreground pointer-events-none" />
          <Input
            ref={searchRef}
            defaultValue={filters.q}
            onChange={handleSearchChange}
            placeholder="Search clients…"
            className="h-9 pl-9 text-sm max-w-sm"
          />
        </div>

        {/* Tag filter */}
        <Popover>
          <PopoverTrigger render={
            <Button
              variant="outline"
              size="sm"
              className={cn(
                'h-9 gap-1.5',
                filters.tags.length > 0 && 'bg-primary/10 border-primary/20 text-primary'
              )}
            >
              <Tag className="h-3.5 w-3.5" aria-hidden="true" />
              {filters.tags.length > 0 ? `${filters.tags.length} tags` : 'Tags'}
            </Button>
          } />
          <PopoverContent className="w-[240px] p-0" align="start">
            {tagLibrary.length === 0 ? (
              <div className="p-4 text-center space-y-2">
                <p className="text-sm font-medium text-foreground">No tags yet</p>
                <p className="text-xs text-stone-brand">
                  Create tags like VIP or Allergic in Settings to filter clients faster.
                </p>
                <Button
                  size="sm"
                  variant="outline"
                  className="w-full h-8 text-xs"
                  onClick={() => {
                    window.location.href = '/settings/tags'
                  }}
                >
                  Go to Settings → Tags
                </Button>
              </div>
            ) : (
              <Command>
                <CommandInput placeholder="Search tags…" className="h-9" />
                <CommandList>
                  <CommandEmpty>No tags match</CommandEmpty>
                  <CommandGroup>
                    {tagLibrary.map((tag) => (
                      <CommandItem
                        key={tag.id}
                        onSelect={() => toggleTag(tag.id)}
                        className="flex items-center gap-2"
                      >
                        <Checkbox
                          checked={filters.tags.includes(tag.id)}
                          className="pointer-events-none"
                          aria-hidden
                        />
                        <span className={cn('h-2 w-2 rounded-full shrink-0', `tag-chip-${tag.color}`)} />
                        <span className="flex-1 text-sm">{tag.name}</span>
                      </CommandItem>
                    ))}
                  </CommandGroup>
                  {filters.tags.length > 0 && (
                    <div className="border-t border-border/40 p-1">
                      <Button variant="ghost" size="sm" className="w-full h-7 text-xs" onClick={() => set('tags', [])}>
                        Clear tags
                      </Button>
                    </div>
                  )}
                </CommandList>
              </Command>
            )}
          </PopoverContent>
        </Popover>

        {/* Artist facet */}
        {artists.length > 0 && (
          <Popover>
            <PopoverTrigger render={
              <Button
                variant="outline"
                size="sm"
                className={cn(
                  'h-9 gap-1.5',
                  filters.artistIds.length > 0 && 'bg-primary/10 border-primary/20 text-primary'
                )}
              >
                <UserCircle className="h-3.5 w-3.5" aria-hidden="true" />
                {filters.artistIds.length > 0 ? `${filters.artistIds.length} artist${filters.artistIds.length !== 1 ? 's' : ''}` : 'Artist'}
              </Button>
            } />
            <PopoverContent className="w-[220px] p-0" align="start">
              <Command>
                <CommandInput placeholder="Search artists…" className="h-9" />
                <CommandList>
                  <CommandEmpty>No artists found</CommandEmpty>
                  <CommandGroup>
                    {artists.map((artist) => (
                      <CommandItem
                        key={artist.id}
                        onSelect={() => toggleArtist(artist.id)}
                        className="flex items-center gap-2"
                      >
                        <Checkbox
                          checked={filters.artistIds.includes(artist.id)}
                          className="pointer-events-none"
                          aria-hidden
                        />
                        <span className="flex-1 text-sm">{artist.display_name}</span>
                      </CommandItem>
                    ))}
                  </CommandGroup>
                  {filters.artistIds.length > 0 && (
                    <div className="border-t border-border/40 p-1">
                      <Button variant="ghost" size="sm" className="w-full h-7 text-xs" onClick={() => set('artistIds', [])}>
                        Clear
                      </Button>
                    </div>
                  )}
                </CommandList>
              </Command>
            </PopoverContent>
          </Popover>
        )}

        {/* Service facet */}
        {services.length > 0 && (
          <Popover>
            <PopoverTrigger render={
              <Button
                variant="outline"
                size="sm"
                className={cn(
                  'h-9 gap-1.5',
                  filters.serviceIds.length > 0 && 'bg-primary/10 border-primary/20 text-primary'
                )}
              >
                <Tag className="h-3.5 w-3.5" aria-hidden="true" />
                {filters.serviceIds.length > 0 ? `${filters.serviceIds.length} service${filters.serviceIds.length !== 1 ? 's' : ''}` : 'Service'}
              </Button>
            } />
            <PopoverContent className="w-[220px] p-0" align="start">
              <Command>
                <CommandInput placeholder="Search services…" className="h-9" />
                <CommandList>
                  <CommandEmpty>No services found</CommandEmpty>
                  <CommandGroup>
                    {services.map((service) => (
                      <CommandItem
                        key={service.id}
                        onSelect={() => toggleService(service.id)}
                        className="flex items-center gap-2"
                      >
                        <Checkbox
                          checked={filters.serviceIds.includes(service.id)}
                          className="pointer-events-none"
                          aria-hidden
                        />
                        <span className="flex-1 text-sm">{service.name}</span>
                      </CommandItem>
                    ))}
                  </CommandGroup>
                  {filters.serviceIds.length > 0 && (
                    <div className="border-t border-border/40 p-1">
                      <Button variant="ghost" size="sm" className="w-full h-7 text-xs" onClick={() => set('serviceIds', [])}>
                        Clear
                      </Button>
                    </div>
                  )}
                </CommandList>
              </Command>
            </PopoverContent>
          </Popover>
        )}

        {/* VIP filter — 5 spending tiers (replaces former vip toggle + separate LTV filter per Clients Audit v1) */}
        <Popover>
          <PopoverTrigger render={
            <Button
              variant="outline"
              size="sm"
              className={cn('h-9 gap-1.5', filters.spendingTier && 'bg-primary/10 border-primary/20 text-primary')}
            >
              <Star className="h-3.5 w-3.5" aria-hidden="true" />
              VIP
              {filters.spendingTier && (
                <span className="ml-1 text-xs opacity-70">
                  {SPENDING_OPTIONS.find((o) => o.value === filters.spendingTier)?.label}
                </span>
              )}
            </Button>
          } />
          <PopoverContent className="w-[200px] p-1" align="start">
            <div className="space-y-0.5">
              {SPENDING_OPTIONS.map((opt) => (
                <button
                  key={opt.value || '__any'}
                  type="button"
                  className={cn(
                    'w-full text-left text-sm px-2.5 py-1.5 rounded-md hover:bg-muted transition-colors',
                    filters.spendingTier === opt.value && 'bg-primary/10 text-primary'
                  )}
                  onClick={() => set('spendingTier', opt.value)}
                >
                  {opt.label}
                </button>
              ))}
            </div>
          </PopoverContent>
        </Popover>

        {/* Last visit range */}
        <Popover>
          <PopoverTrigger render={
            <Button
              variant="outline"
              size="sm"
              className={cn('h-9 gap-1.5', filters.lastVisitRange && 'bg-primary/10 border-primary/20 text-primary')}
            >
              <Clock className="h-3.5 w-3.5" aria-hidden="true" />
              {filters.lastVisitRange
                ? LAST_VISIT_OPTIONS.find((o) => o.value === filters.lastVisitRange)?.label ?? 'Last visit'
                : 'Last visit'}
            </Button>
          } />
          <PopoverContent className="w-[200px] p-1" align="start">
            <div className="space-y-0.5">
              {LAST_VISIT_OPTIONS.map((opt) => (
                <button
                  key={opt.value || '__any'}
                  type="button"
                  className={cn(
                    'w-full text-left text-sm px-2.5 py-1.5 rounded-md hover:bg-muted transition-colors',
                    filters.lastVisitRange === opt.value && 'bg-primary/10 text-primary'
                  )}
                  onClick={() => set('lastVisitRange', opt.value)}
                >
                  {opt.label}
                </button>
              ))}
            </div>
          </PopoverContent>
        </Popover>

        {/* No-shows toggle */}
        <Button
          variant="outline"
          size="sm"
          className={cn(
            'h-9 gap-1.5',
            filters.noShows && 'bg-destructive/10 border-destructive/20 text-destructive'
          )}
          onClick={() => set('noShows', !filters.noShows)}
        >
          <AlertTriangle className="h-3.5 w-3.5" aria-hidden="true" />
          No-shows
        </Button>

        {/* Has allergy/medical alerts toggle */}
        <Button
          variant="outline"
          size="sm"
          className={cn(
            'h-9 gap-1.5',
            filters.hasAlerts && 'bg-destructive/10 border-destructive/20 text-destructive'
          )}
          onClick={() => set('hasAlerts', !filters.hasAlerts)}
        >
          <Stethoscope className="h-3.5 w-3.5" aria-hidden="true" />
          Has alerts
        </Button>

        {/* Column toggle placeholder — wired in ClientsPageClient */}
        <div className="ml-auto flex items-center gap-2">
          <Button
            id="column-toggle-trigger"
            variant="outline"
            size="sm"
            className="h-9 gap-1.5"
            aria-label="Configure columns"
          >
