import { TransactionsTab } from '@/components/payments/tabs/TransactionsTab'
import { CommissionsTab } from '@/components/payments/tabs/CommissionsTab'
import { PayrollTab } from '@/components/payments/tabs/PayrollTab'
import type { PlanTier } from '@/lib/billing/feature-gate'
import type { NavRole } from '@/components/app/sidebar/nav-config'
import type { PageTab } from '@/components/shared/PageTabs'
import { PageShell } from '@/components/shared/PageShell'

export const metadata: Metadata = {
  title: 'Payments — InkOS',
}

const VALID_TABS = ['transactions', 'commissions', 'payroll'] as const
type TabKey = (typeof VALID_TABS)[number]

interface SearchParams {
  tab?: string
}

function resolveTab(searchParams: SearchParams, role: NavRole): TabKey {
  const requested = searchParams.tab as TabKey | undefined
  if (requested && VALID_TABS.includes(requested)) {
    // Artists can only access commissions tab
    if (role === 'artist' && requested !== 'commissions') {
      return 'commissions'
    }
    return requested
  }
  // Default tab by role
  if (role === 'artist') return 'commissions'
  return 'transactions'
}

const PAYMENT_TABS: PageTab[] = [
  {
    key: 'transactions',
    label: 'Transactions',
    href: '/payments?tab=transactions',
    hidden: (role) => role === 'artist',
  },
  {
    key: 'commissions',
    label: 'Commissions',
    href: '/payments?tab=commissions',
    gated: 'studio',
    hidden: (role) => role === 'receptionist',
  },
  {
    key: 'payroll',
    label: 'Payroll',
    href: '/payments?tab=payroll',
    gated: 'pro',
    hidden: (role) => role === 'artist' || role === 'receptionist',
  },
]

const TabSkeleton = () => (
  <div className="p-6 space-y-4">
    <Skeleton className="h-8 w-32" />
    <Skeleton className="h-4 w-64" />
    <div className="space-y-2">
      {Array.from({ length: 8 }).map((_, i) => (
        <Skeleton key={i} className="h-12 w-full rounded-lg" />
      ))}
    </div>
  </div>
)

export default async function PaymentsPage({
  searchParams,
}: {
  searchParams: Promise<SearchParams>
}) {
  const supabase = await createClient()
  const {
    data: { user },
  } = await supabase.auth.getUser()

  if (!user) redirect('/login')

  let activeStudio: Awaited<ReturnType<typeof getActiveStudio>>
  try {
    activeStudio = await getActiveStudio()
  } catch (err) {
    if (err instanceof NoStudioMembershipError) redirect('/onboarding')
    redirect('/onboarding')
  }

  const { role, plan } = activeStudio
  const resolvedParams = await searchParams
  const activeTab = resolveTab(resolvedParams, role as NavRole)

  return (
    <PageShell>
      <PageHeader
        title="Payments"
        description="Transactions, commissions, and payroll in one place"
      />

      <PageViews>
        <PageTabs
          tabs={filterTabsForRole(PAYMENT_TABS, role as NavRole)}
          activeKey={activeTab}
          currentPlan={plan as PlanTier}
          currentRole={role as NavRole}
        />
      </PageViews>

      <div className="flex-1">
        {activeTab === 'transactions' && (
          <Suspense fallback={<TabSkeleton />}>
            <TransactionsTab />
          </Suspense>
        )}
        {activeTab === 'commissions' && (
          <Suspense fallback={<TabSkeleton />}>
            <CommissionsTab />
          </Suspense>
        )}
        {activeTab === 'payroll' && (
          <Suspense fallback={<TabSkeleton />}>
            <PayrollTab />
          </Suspense>
        )}
      </div>
    </PageShell>
  )
}

'use client'

import { useRef } from 'react'
import { useRouter, usePathname } from 'next/navigation'
import { cn } from '@/lib/utils'
import { PlanBadge } from '@/components/shared/PlanBadge'
import { PLAN_ORDER } from '@/lib/billing/feature-gate'
import type { PlanTier } from '@/lib/billing/feature-gate'
import type { NavRole } from '@/components/app/sidebar/nav-config'

export interface PageTab {
  key: string
  label: string
  href: string
  badge?: number | string
  gated?: PlanTier
  /** Return true to hide this tab for the given role */
  hidden?: (role: NavRole) => boolean
}

export interface PageTabsProps {
  tabs: PageTab[]
  activeKey: string
  currentPlan: PlanTier
  currentRole: NavRole
  className?: string
}

/**
 * S13 — Horizontal underline tab row with URL persistence via ?tab= query param.
 *
 * Accessibility:
 *  - role="tablist" on container
 *  - role="tab" + aria-selected on each trigger
 *  - Arrow key navigation within the tab row (ARIA authoring practices)
 *  - focus-visible ring on each trigger
 *
 * URL persistence:
 *  - Active tab read from ?tab= param by parent; defaulted to tabs[0].key if absent/invalid
 *  - Navigates via router.replace({pathname}?tab={key}, { scroll: false }) — no full reload
 *
 * Plan gating:
 *  - If tab.gated is set and user plan is below requirement, renders tab at reduced opacity
 *  - Click on gated tab routes to /settings/billing
 */
export function PageTabs({ tabs, activeKey, currentPlan, currentRole, className }: PageTabsProps) {
  const router = useRouter()
  const pathname = usePathname()
  const listRef = useRef<HTMLDivElement>(null)

  const visibleTabs = tabs.filter((t) => !(t.hidden?.(currentRole) ?? false))

  function isLocked(tab: PageTab): boolean {
    return tab.gated != null && PLAN_ORDER[currentPlan] < PLAN_ORDER[tab.gated]
  }

  function handleSelect(tab: PageTab) {
    if (isLocked(tab)) {
      router.push('/settings/billing')
      return
    }
    router.replace(`${pathname}?tab=${tab.key}`, { scroll: false })
  }

  function handleKeyDown(e: React.KeyboardEvent<HTMLButtonElement>, currentIndex: number) {
    const triggers = listRef.current?.querySelectorAll<HTMLButtonElement>('[role="tab"]')
    if (!triggers) return

    let nextIndex: number | null = null

    if (e.key === 'ArrowRight') {
      nextIndex = (currentIndex + 1) % triggers.length
    } else if (e.key === 'ArrowLeft') {
      nextIndex = (currentIndex - 1 + triggers.length) % triggers.length
    } else if (e.key === 'Home') {
      nextIndex = 0
    } else if (e.key === 'End') {
      nextIndex = triggers.length - 1
    }

    if (nextIndex !== null) {
      e.preventDefault()
      triggers[nextIndex]?.focus()
    }
  }

  return (
    <div
      ref={listRef}
      role="tablist"
      aria-label="Page sections"
      className={cn(
        'flex items-end gap-0 border-b border-border/60',
        'overflow-x-auto scrollbar-none',
        // Fade edges on mobile only
        '[mask-image:linear-gradient(to_right,transparent_0px,black_16px,black_calc(100%-16px),transparent_100%)]',
        'md:[mask-image:none]',
        className,
      )}
    >
      {visibleTabs.map((tab, index) => {
        const isActive = tab.key === activeKey
        const locked = isLocked(tab)

        return (
          <button
            key={tab.key}
            type="button"
            role="tab"
            aria-selected={isActive}
            onClick={() => handleSelect(tab)}
            onKeyDown={(e) => handleKeyDown(e, index)}
            className={cn(
              'relative flex items-center gap-1.5 px-3 h-10 shrink-0',
              'text-sm whitespace-nowrap transition-colors duration-150',
              'focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-0',
              isActive
                ? [
                    'font-semibold text-foreground',
                    'after:absolute after:bottom-0 after:inset-x-0 after:h-0.5 after:bg-primary after:rounded-full',
                  ]
                : 'font-medium text-muted-foreground hover:text-foreground',
              locked && 'opacity-60 cursor-default',
            )}
          >
            {tab.label}
            {tab.gated != null && <PlanBadge plan={tab.gated} />}
            {tab.badge != null && (
              <span className="inline-flex items-center rounded-full bg-muted text-muted-foreground text-[10px] font-semibold leading-none px-1.5 py-0.5 min-w-[18px] justify-center tabular-nums">
                {tab.badge}
              </span>
            )}
          </button>
        )
      })}
    </div>
  )
}

'use client'

import { useState } from 'react'
import { X, Tag, XCircle, Download, Archive, Loader2 } from 'lucide-react'
import { toast } from 'sonner'
import { Button } from '@/components/ui/button'
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '@/components/ui/popover'
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from '@/components/ui/command'
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from '@/components/ui/alert-dialog'
import { Checkbox } from '@/components/ui/checkbox'
import { TagChip, type ClientTag } from './TagChip'
import { cn } from '@/lib/utils'

interface BulkActionsBarProps {
  selectedIds: string[]
  tagLibrary: ClientTag[]
  onClearSelection: () => void
  onArchived: () => void
  onTagsApplied: () => void
}

export function BulkActionsBar({
  selectedIds,
  tagLibrary,
  onClearSelection,
  onArchived,
  onTagsApplied,
}: BulkActionsBarProps) {
  const [addTagIds, setAddTagIds] = useState<string[]>([])
  const [removeTagIds, setRemoveTagIds] = useState<string[]>([])
  const [isArchiving, setIsArchiving] = useState(false)
  const [isTagging, setIsTagging] = useState(false)
  const [isExporting, setIsExporting] = useState(false)

  async function handleApplyTags(action: 'add' | 'remove') {
    const tagSlugs = action === 'add'
      ? tagLibrary.filter((t) => addTagIds.includes(t.id)).map((t) => t.id)
      : tagLibrary.filter((t) => removeTagIds.includes(t.id)).map((t) => t.id)

    if (tagSlugs.length === 0) return
    setIsTagging(true)

    try {
      const res = await fetch('/api/clients/bulk-tag', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ client_ids: selectedIds, tag_slugs: tagSlugs, action }),
      })
      if (!res.ok) {
        const json = await res.json() as { error?: string }
        throw new Error(json.error ?? 'Failed to update tags')
      }
      toast.success(`Tags ${action === 'add' ? 'applied' : 'removed'}`)
      if (action === 'add') setAddTagIds([])
      else setRemoveTagIds([])
      onTagsApplied()
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to update tags'
      toast.error(message)
    } finally {
      setIsTagging(false)
    }
  }

  async function handleArchive() {
    setIsArchiving(true)
    try {
      await Promise.all(
        selectedIds.map((id) =>
          fetch(`/api/clients/${id}`, { method: 'DELETE' })
        )
      )
      toast.success(`${selectedIds.length} client${selectedIds.length !== 1 ? 's' : ''} archived`, {
        action: {
          label: 'Undo',
          onClick: async () => {
            await Promise.all(
              selectedIds.map((id) => fetch(`/api/clients/${id}/restore`, { method: 'POST' }))
            )
            toast.success('Restored')
            onArchived()
          },
        },
      })
      onClearSelection()
      onArchived()
    } catch {
      toast.error('Failed to archive clients')
    } finally {
      setIsArchiving(false)
    }
  }

  async function handleExport() {
    setIsExporting(true)
    const toastId = toast.loading('Preparing export…')
    try {
      const ids = selectedIds.join(',')
      const res = await fetch(`/api/clients/export?ids=${ids}`)
      if (!res.ok) throw new Error('Export failed')
      const blob = await res.blob()
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url
      a.download = `clients-${new Date().toISOString().slice(0, 10)}.csv`
      a.click()
      URL.revokeObjectURL(url)
      toast.success('Downloading', { id: toastId })
    } catch {
      toast.error('Export failed', { id: toastId })
    } finally {
      setIsExporting(false)
    }
  }

  if (selectedIds.length === 0) return null

  return (
    <div
      className={cn(
        'flex items-center justify-between gap-3 px-4 py-2.5',
        'bg-primary/[0.08] border border-primary/20 rounded-lg',
        'animate-in fade-in-0 slide-in-from-top-2 duration-150'
      )}
    >
      <div className="flex items-center gap-2">
        <span className="h-2 w-2 rounded-full bg-primary" />
        <span className="text-sm font-medium">
          {selectedIds.length} client{selectedIds.length !== 1 ? 's' : ''} selected
        </span>
      </div>

      <div className="flex items-center gap-1.5">
        {/* Apply tag */}
        <Popover>
          <PopoverTrigger render={<Button variant="outline" size="sm" className="h-9 gap-1.5" disabled={isTagging}><Tag className="h-3.5 w-3.5" />Add tag</Button>} />
          <PopoverContent className="w-[220px] p-0" align="end">
            <Command>
              <CommandInput placeholder="Search tags…" className="h-8" />
              <CommandList>
                <CommandEmpty>No tags found</CommandEmpty>
                <CommandGroup>
                  {tagLibrary.map((tag) => (
                    <CommandItem
                      key={tag.id}
                      onSelect={() =>
                        setAddTagIds((prev) =>
                          prev.includes(tag.id) ? prev.filter((id) => id !== tag.id) : [...prev, tag.id]
                        )
                      }
                    >
                      <Checkbox checked={addTagIds.includes(tag.id)} className="mr-2 pointer-events-none" aria-hidden />
                      <TagChip tag={tag} size="sm" />
                    </CommandItem>
                  ))}
                </CommandGroup>
              </CommandList>
              {addTagIds.length > 0 && (
                <div className="border-t border-border/40 p-2">
                  <Button
                    size="sm"
                    className="w-full h-7"
                    onClick={() => handleApplyTags('add')}
                    disabled={isTagging}
                  >
                    {isTagging ? <Loader2 aria-hidden="true" className="h-3.5 w-3.5 animate-spin" /> : 'Apply tags'}
                  </Button>
                </div>
              )}
            </Command>
          </PopoverContent>
        </Popover>

        {/* Remove tag */}
        <Popover>
          <PopoverTrigger render={<Button variant="outline" size="sm" className="h-9 gap-1.5" disabled={isTagging}><XCircle className="h-3.5 w-3.5" />Remove tag</Button>} />
          <PopoverContent className="w-[220px] p-0" align="end">
            <Command>
              <CommandInput placeholder="Search tags…" className="h-8" />
              <CommandList>
                <CommandEmpty>No tags found</CommandEmpty>
                <CommandGroup>
                  {tagLibrary.map((tag) => (
                    <CommandItem
                      key={tag.id}
                      onSelect={() =>
                        setRemoveTagIds((prev) =>
                          prev.includes(tag.id) ? prev.filter((id) => id !== tag.id) : [...prev, tag.id]
                        )
                      }
                    >
                      <Checkbox checked={removeTagIds.includes(tag.id)} className="mr-2 pointer-events-none" aria-hidden />
                      <TagChip tag={tag} size="sm" />
                    </CommandItem>
                  ))}
                </CommandGroup>
              </CommandList>
              {removeTagIds.length > 0 && (
                <div className="border-t border-border/40 p-2">
                  <Button
                    size="sm"
                    variant="destructive"
                    className="w-full h-7"
                    onClick={() => handleApplyTags('remove')}
                    disabled={isTagging}
                  >
                    {isTagging ? <Loader2 aria-hidden="true" className="h-3.5 w-3.5 animate-spin" /> : 'Remove tags'}
                  </Button>
                </div>
              )}
            </Command>
          </PopoverContent>
        </Popover>

        {/* Export */}
        <Button
          variant="outline"
          size="sm"
          className="h-9 gap-1.5"
          onClick={handleExport}
          disabled={isExporting}
        >
          {isExporting ? <Loader2 aria-hidden="true" className="h-3.5 w-3.5 animate-spin" /> : <Download className="h-3.5 w-3.5" />}
          Export CSV
        </Button>

        {/* Archive */}
        <AlertDialog>
          <AlertDialogTrigger
            render={
              <Button
                variant="outline"
                size="sm"
                className="h-9 gap-1.5"
                loading={isArchiving}
                loadingLabel="Archiving..."
              >
                <Archive className="h-3.5 w-3.5" />
                Archive
              </Button>
            }
          />
          <AlertDialogContent>
            <AlertDialogHeader>
              <AlertDialogTitle>Archive {selectedIds.length} client{selectedIds.length !== 1 ? 's' : ''}?</AlertDialogTitle>
              <AlertDialogDescription>
                They will be hidden from your client list and won&apos;t appear in new bookings. You can restore them from the archived view.
              </AlertDialogDescription>
            </AlertDialogHeader>
            <AlertDialogFooter>
              <AlertDialogCancel>Cancel</AlertDialogCancel>
              <AlertDialogAction
                onClick={handleArchive}
                className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
              >
                {isArchiving ? <Loader2 aria-hidden="true" className="h-4 w-4 animate-spin" /> : 'Archive'}
              </AlertDialogAction>
            </AlertDialogFooter>
          </AlertDialogContent>
        </AlertDialog>

        {/* Clear selection */}
        <Button
          variant="ghost"
          size="icon"
          className="h-8 w-8"
          onClick={onClearSelection}
          aria-label="Clear selection"
        >
          <X className="h-4 w-4" />
        </Button>
      </div>
    </div>
  )
}

