  useEffect(() => {
    if (open) {
      setName(mode === 'edit' && view ? view.name : '')
      setScope(mode === 'edit' && view ? view.scope : 'private')
    }
  }, [open, mode, view])

  async function handleSave() {
    const trimmedName = name.trim()
    if (!trimmedName) return

    setSaving(true)
    try {
      const endpoint =
        mode === 'edit' && view
          ? `/api/client-views/${view.id}`
          : '/api/client-views'
      const method = mode === 'edit' ? 'PATCH' : 'POST'

      const payload =
        mode === 'create'
          ? { name: trimmedName, scope, filters: currentFilters }
          : { name: trimmedName, scope }

      const res = await fetch(endpoint, {
        method,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      })

      if (!res.ok) {
        const json = await res.json() as { error?: string }
        throw new Error(json.error ?? 'Failed to save view')
      }

      const json = await res.json() as { data: ClientView }
      toast.success(mode === 'create' ? 'View created' : 'View updated')
      onSaved(json.data)
      onOpenChange(false)
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Failed to save view'
      toast.error(message)
    } finally {
      setSaving(false)
    }
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-md">
        <DialogHeader>
          <DialogTitle>{mode === 'create' ? 'New view' : 'Edit view'}</DialogTitle>
          <DialogDescription>

